mapper.select:
select applicant_organization_id as id, SUM(json_form -> '$.recruitNum') as num from flow_form_data WHERE 1 = 1
AND apply_done_time BETWEEN #{param.period.begin} AND #{param.period.end}
AND business_type = 'PERSONNEL_RECRUIT' AND status = 'PASS' GROUP BY applicant_organization_id

select p.`name` as `post_name`, JSON_EXTRACT(f.`json_form`,'$.recruitNum') as `num`, f.`applicant_name`, f.`apply_time`, f.`apply_done_time` from `flow_form_data` f LEFT JOIN `cube-biz-ouaa`.`position` p ON REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') = CONCAT('',p.`id`) WHERE 1 = 1
AND f.`apply_done_time` BETWEEN #{param.period.begin} AND #{param.period.end}
AND f.`business_type` = 'PERSONNEL_RECRUIT' AND f.`status` = 'PASS' AND REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') = #{id}

mapper.sql:
select REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') as `id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') as `post_id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.organizationIdList[0]'),'"','') as `organization_id`, COUNT(*) as `num` from `flow_form_data` f WHERE 1 = 1
AND f.`apply_done_time` BETWEEN #{param.period.begin} AND #{param.period.end}
AND f.`business_type` = 'PERSONNEL_INDUCTION' AND f.`status` = 'PASS' AND LENGTH(JSON_EXTRACT(f.`json_form`,'$.postId')) != 0 GROUP BY JSON_EXTRACT(f.`json_form`,'$.postId') ORDER BY `num` DESC

mapper.select:
select REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') as `id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') as `post_id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.organizationIdList[0]'),'"','') as `organization_id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.staffName'),'"','') AS `staffName`, f.`applicant_name`, f.`apply_time`, f.`apply_done_time` from `flow_form_data` f WHERE 1 = 1
AND f.`apply_done_time` BETWEEN #{param.period.begin} AND #{param.period.end}
AND f.`business_type` = 'PERSONNEL_INDUCTION' AND f.`status` = 'PASS' AND REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') = #{id}

mapper.sql:
SELECT t.`id`, t.`id` as post_id, t.`organization_name`, COUNT( t.id ) AS `num`, COUNT( CASE WHEN t.`assessResult` = 'A' THEN '1' END ) AS `outstandingNum`, COUNT( CASE WHEN t.`assessResult` = 'B' THEN '1' END ) AS `qualifiedNum`, COUNT( CASE WHEN t.`assessResult` > 'B' THEN '1' END ) AS `unqualifiedNum` FROM ( SELECT a.applicant_post_id AS id, `applicant_organization_name` AS `organization_name`, REPLACE(JSON_EXTRACT(`json_form`,'$.assessResult'),'"','') AS `assessResult`, JSON_EXTRACT(`json_form`,'$.assessScore') AS `assessScore`, JSON_EXTRACT(`json_form`,'$.assessTime') AS `assessTime`, `applicant_name` FROM `flow_form_data` a WHERE `business_type` = 'PERSONNEL_PROBATION_ASSESS' AND a.`status` = 'PASS'
AND a.`apply_done_time` BETWEEN #{param.period.begin} AND #{param.period.end}
) t where LENGTH(t.`id`) != 0 GROUP BY t.`id` ORDER BY `num` DESC

SELECT REPLACE(JSON_EXTRACT(f.`json_form`,'$.organizationId'),'"','') AS `id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.organizationId'),'"','') AS `organization_id`, REPLACE(JSON_EXTRACT(f.`json_form`,'$.postId'),'"','') AS `postId`, COUNT( REPLACE(JSON_EXTRACT(f.`json_form`,'$.organizationId'),'"','') ) AS `num` FROM `flow_form_data` f WHERE f.`business_type` = 'PERSONNEL_REGULAR_WORKER' AND f.`status` = 'PASS' AND LENGTH(JSON_EXTRACT(f.`json_form`,'$.organizationId')) != 0
AND apply_done_time BETWEEN #{param.period.begin} AND #{param.period.end}
GROUP BY JSON_EXTRACT(f.`json_form`,'$.organizationId')

SELECT t.`id`, t.`post_id`, t.`organization_id`, COUNT( t.`id` ) AS `num` FROM ( SELECT REPLACE(JSON_EXTRACT(a.`json_form`,'$.postId'),'"','') AS `id`, REPLACE(JSON_EXTRACT(a.`json_form`,'$.postId'),'"','') AS `post_id`, REPLACE(JSON_EXTRACT(a.json_form,'$.organizationId'),'"','') AS `organization_id` FROM `flow_form_data` a WHERE `business_type` = 'PERSONNEL_LEAVE_OFFICE' AND a.`status` = 'PASS'
AND a.`apply_done_time` BETWEEN #{param.period.begin} AND #{param.period.end}
) t WHERE LENGTH(t.`id`) != 0 GROUP BY t.`id`

SELECT `rotation_organization_id` as `id`, COUNT( * ) AS `num` FROM `flow_form_data_details` f inner join `flow_form_data` d on d.`id`=f.`flow_form_data_id` where d.`business_type` = 'PERSONNEL_ROTATION_POST' AND d.`status` = 'PASS'
AND d.`apply_done_time` BETWEEN #{param.period.begin} AND #{param.period.end}
GROUP BY `rotation_organization_id`
